fn main() -> Int {
  let v = Vec[Int]();
  v.push(1); v.push(2); v.push(3); v.push(4); v.push(5); v.push(6);

  var sum = 0;
  for n in v {
    if n % 2 == 1 {
      sum = sum + n;
    }
  }
  return sum;
}
